/**
 * @fileoverview Test the usage of a removed Class
 * @author Sencha
 */
'use strict';

// ------------------------------------------------------------------------------
// Requirements
// ------------------------------------------------------------------------------

const rule = require('../../../lib/rules/no-removed-class-usage'),
    RuleTester = require('eslint').RuleTester;

// ------------------------------------------------------------------------------
// Tests
// ------------------------------------------------------------------------------

const ruleTester = new RuleTester();
ruleTester.run('no-removed-class-usage', rule, {

    valid: [

    ],

    invalid: [
        // TODO - add this once we include the doxi json for 5.0.0
        // {
        //     settings: {
        //         extjs: {
        //             fromVersion: '5.0.0',
        //             toVersion: '7.0.0'
        //         }
        //     },
        //     code: `
        //         Ext.define('MyCustomClass', {
        //             extend: 'Ext.data.proxy.Sql'
        //         });
        //     `,
        //     errors: [
        //         { message: /Usage of removed Class 'Ext.data.proxy.Sql' found.*/ }
        //     ]
        // },
        {
            settings: {
                extjs: {
                    fromVersion: '4.1',
                    toVersion: '7.9'
                }
            },
            code: `
                Ext.define('User', {
                    extend: 'Ext.data.Model',
                    fields: ['first', 'last']
                });
                Ext.ModelManager.create({
                    first: 'Jack',
                    last: 'Ratcliff'
                }, 'User');
            `,
            errors: [
                { message: /Usage of removed Class 'Ext.ModelManager' found/ }
            ]
        },
        {
            settings: {
                extjs: {
                    fromVersion: '4.1',
                    toVersion: '7.9.0'
                }
            },
            code: `
                // should warn due to NewExpression
                var cl = new Ext.layout.ClassList();

                // should warn due to MemberExpression
                var xClass = Ext.layout.ClassList;
                var cl2 = new xClass();

                // should warn due to Property
                Ext.create({
                    xclass: 'Ext.layout.ClassList'
                });

                // should warn do to MemberExpression
                Ext.layout.ClassList.add('myCls')

                Ext.define('MyCustomClass', {
                    // should warn due to Property
                    extend: 'Ext.layout.ClassList',

                    // should warn do to MemberExpression
                    constructor: function () {
                        // should warn due to MemberExpression
                        var xClass = Ext.layout.ClassList;
                        var cl = new xClass();
                    }
                });
            `,
            errors: [
                { 
                    message: /Usage of removed Class 'Ext.layout.ClassList' found/,
                    type: 'NewExpression'
                },
                { 
                    message: /Usage of removed Class 'Ext.layout.ClassList' found/,
                    type: 'MemberExpression'
                },
                { 
                    message: /Usage of removed Class 'Ext.layout.ClassList' found/,
                    type: 'Property'
                },
                { 
                    message: /Usage of removed Class 'Ext.layout.ClassList' found/,
                    type: 'MemberExpression'
                },
                { 
                    message: /Usage of removed Class 'Ext.layout.ClassList' found/,
                    type: 'Property'
                },
                { 
                    message: /Usage of removed Class 'Ext.layout.ClassList' found/,
                    type: 'MemberExpression'
                }
            ]
        }
    ]
});
